#!/bin/bash\nexport NCD_TEST_MODE=1\nTESTROOT=/tmp/ncd_tree_test_999\nmkdir -p "$TESTROOT/Projects/alpha/src"\nmkdir -p "$TESTROOT/Projects/beta/src"\nexport XDG_DATA_HOME=/tmp/ncd_tree_meta_999\nmkdir -p "$XDG_DATA_HOME"\ncd "$TESTROOT" && /mnt/e/llama/NewChangeDirectory/NewChangeDirectory -r . >/dev/null 2>&1\necho "=== JSON ==="\n/mnt/e/llama/NewChangeDirectory/NewChangeDirectory --agent tree "$TESTROOT/Projects/alpha" --json 2>&1\necho "=== FLAT ==="\n/mnt/e/llama/NewChangeDirectory/NewChangeDirectory --agent tree "$TESTROOT/Projects/alpha" --flat 2>&1\necho "=== Check DB ==="\nls -la "$XDG_DATA_HOME/ncd/"\nrm -rf "$TESTROOT" "$XDG_DATA_HOME"\n